#include <vector>
#include <map>
#include <set>
#include <queue>
#include <ctime>
#include <cassert>
#include <list>
#include <bitset>
using namespace std;

#define f first
#define s second
#define pb push_back
#define mp make_pair
#define forit(v,it) for(typeof(v.begin()) it = v.begin(); it != v.end(); ++it)

typedef long long ll;
typedef pair<int, int> pii;
typedef vector<int> vi;

int n;
double R, r;
const long double PI = 3.1415926535897932384626433832795L;

int main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    scanf("%d%lf%lf", &n, &R, &r);

    int cnt = 0;

    if (R < r || (n > 1 && R == r)) {
        puts("NO");
        return 0;
    }

    if (n == 1) {
        puts("YES");
        return 0;
    }

    while (R >= r) {
        if (R == r) {
            cnt++;
            break;
        }

        long double x = acos(1 - (long double)(2 * r * r) /
                                      ((R - r) * (R - r)));
        if (x + 1e-9 < 0)
            x += 2 * PI;

        cnt += (int)((2 * PI) / x + 1e-9);
        R -= 2 * r;
    }

    puts(cnt < n ? "NO" : "YES");
    return 0;
}

